function DeletePuzzleModal(props) {
  const DeletePuzzle = async () => {
    const userRef = doc(db, 'users', props.user.uid);
    await updateDoc(userRef, {
      puzzles: arrayRemove(props.puzzle)
    });
    props.setChangedPuzzleList(Math.random());
    console.log(props.changedPuzzleList);
    props.toggleModal();
  }

  return (
    <>
      <h2>Delete Puzzle</h2>
      <button onClick={DeletePuzzle}>Confirm Delete</button>
    </>
  )
}

 function PuzzlesBoard(props) {

  if(props.puzzleList) return (
    <div className='puzzleBoard'>
      {props.puzzleList.map(puzzle => <PuzzleCard puzzle={puzzle} user={props.user} 
      changedPuzzleList={props.changedPuzzleList}
       setChangedPuzzleList={props.setChangedPuzzleList}
       toggleModal={props.toggleModal}/>)}
    </div>
  )
}

function PuzzleCard(props) {
  return (
    <div className='puzzleCard'>
      <p>{props.puzzle}</p>
      <button id='delete' value={props.puzzle} className='delete-puzzle' onClick={props.toggleModal}>Delete</button>
    </div>
  )
}

export default App;
